(function(){'use strict';var state={results:null,history:[],lastToken:''};var elements={};

function init(){elements={algoSelect:document.getElementById('jwtg-algo'),headerInput:document.getElementById('jwtg-header'),payloadInput:document.getElementById('jwtg-payload'),secretInput:document.getElementById('jwtg-secret'),secretField:document.getElementById('jwtg-secret-field'),generateBtn:document.getElementById('generate-btn'),resetBtn:document.getElementById('reset-btn'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultArea:document.getElementById('result-area'),tokenDisplay:document.getElementById('jwtg-token'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),statAlgorithm:document.getElementById('stat-algorithm'),statLength:document.getElementById('stat-length'),statParts:document.getElementById('stat-parts'),statTime:document.getElementById('stat-delta')};
elements.generateBtn.addEventListener('click',generate);elements.resetBtn.addEventListener('click',reset);elements.algoSelect.addEventListener('change',onAlgoChange);elements.headerInput.addEventListener('input',onInput);elements.payloadInput.addEventListener('input',onInput);elements.secretInput.addEventListener('input',onInput);
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);showEmptyState();}

function onInput(){var hasHeader=elements.headerInput.value.trim().length>0;var hasPayload=elements.payloadInput.value.trim().length>0;updateStatus(hasHeader&&hasPayload?'ready':'',hasHeader&&hasPayload?'Ready':'');}

function onAlgoChange(){var val=elements.algoSelect.value;elements.secretField.style.display=val==='none'?'none':'block';try{var h=JSON.parse(elements.headerInput.value);h.alg=val;elements.headerInput.value=JSON.stringify(h,null,2);}catch(e){}}
function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}
function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}
function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}

function generate(){var algo=elements.algoSelect.value;var headerStr=elements.headerInput.value.trim();var payloadStr=elements.payloadInput.value.trim();var secret=elements.secretInput.value;
try{JSON.parse(headerStr);}catch(e){showToast('Invalid JSON in header','error');return;}
try{JSON.parse(payloadStr);}catch(e){showToast('Invalid JSON in payload','error');return;}
updateStatus('processing','Generating...');
var t0=performance.now();
setTimeout(function(){try{var headerObj=JSON.parse(headerStr);var payloadObj=JSON.parse(payloadStr);var headerMin=JSON.stringify(headerObj);var payloadMin=JSON.stringify(payloadObj);var headerB64=base64UrlEncode(headerMin);var payloadB64=base64UrlEncode(payloadMin);var signingInput=headerB64+'.'+payloadB64;
if(algo==='none'){var token=signingInput+'.';finish(token,algo,headerStr,payloadStr,secret,t0);return;}
var hashAlgo=algo==='HS256'?'SHA-256':algo==='HS384'?'SHA-384':'SHA-512';
var enc=new TextEncoder();crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:{name:hashAlgo}},false,['sign']).then(function(key){return crypto.subtle.sign('HMAC',key,enc.encode(signingInput));}).then(function(sig){var sigB64=arrayToBase64Url(new Uint8Array(sig));var token=signingInput+'.'+sigB64;finish(token,algo,headerStr,payloadStr,secret,t0);}).catch(function(err){showToast('Error: '+err.message,'error');updateStatus('error','Error');});}catch(e){showToast('Error: '+e.message,'error');updateStatus('error','Error');}},100);}

function finish(token,algo,headerStr,payloadStr,secret,t0){var t1=performance.now();state.lastToken=token;
var parts=token.split('.').length;
var coloredToken=token.replace(/([^.]+)\.([^.]+)\.?(.*)/,'<span class="jwtg-part-header">$1</span>.<span class="jwtg-part-payload">$2</span>.<span class="jwtg-part-signature">$3</span>');
elements.tokenDisplay.innerHTML=coloredToken;elements.tokenDisplay.className='jwtg-token has-token';
var stats={algorithm:algo,token:token,tokenLength:token.length,parts:parts,header:headerStr,payload:payloadStr,secret:secret,time:t1-t0};
state.results=stats;if(state.history.length>=5)state.history.shift();state.history.push(stats);
elements.statAlgorithm.textContent=algo;elements.statLength.textContent=token.length;elements.statParts.textContent=parts;if(elements.statTime)elements.statTime.textContent=(t1-t0)<1?'<1ms':Math.round(t1-t0)+'ms';
var printTitle=document.querySelector('.print-report-title');var printDate=document.querySelector('.print-report-date');if(printTitle)printTitle.textContent='JWT Generator Report';if(printDate)printDate.textContent='Generated on '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
showResults();updateStatus('done','Completed');
if(elements.exportSection)elements.exportSection.style.display='flex';
renderComparison();}

function base64UrlEncode(str){return btoa(unescape(encodeURIComponent(str))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function arrayToBase64Url(arr){var binary='';for(var i=0;i<arr.length;i++)binary+=String.fromCharCode(arr[i]);return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;
var available=state.history.filter(function(item){return!state.results||item.token!==state.results.token;});
if(available.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';
var html='<option value="">Select previous...</option>';
available.forEach(function(item,i){var idx=state.history.indexOf(item);
html+='<option value="'+idx+'">'+item.algorithm+' - '+item.tokenLength+' chars</option>';});
elements.comparisonSelect.innerHTML=html;}

function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);
if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;
var metrics=[{label:'Algorithm',curr:curr.algorithm,prev:prev.algorithm},{label:'Token Length',curr:curr.tokenLength,prev:prev.tokenLength},{label:'Parts',curr:curr.parts,prev:prev.parts}];
var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';
metrics.forEach(function(m){var diff=typeof m.curr==='number'?m.curr-m.prev:0;
var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';
html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});
html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}

function exportCopy(){if(!state.lastToken)return;if(navigator.clipboard){navigator.clipboard.writeText(state.lastToken).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(state.lastToken);}}

function exportTxt(){if(!state.results)return;var r=state.results;var text='JWT Generator Report\n====================\n\nAlgorithm: '+r.algorithm+'\nToken Length: '+r.tokenLength+'\nParts: '+r.parts+'\nHeader: '+r.header+'\nPayload: '+r.payload+'\nSecret: '+(r.secret?'***':'N/A')+'\n\n--- Generated Token ---\n\n'+r.token+'\n';downloadFile('jwt-generated.txt',text,'text/plain');showToast('Downloaded TXT report','success');}

function exportJson(){if(!state.results)return;var r=state.results;var json=JSON.stringify({algorithm:r.algorithm,tokenLength:r.tokenLength,parts:r.parts,header:JSON.parse(r.header),payload:JSON.parse(r.payload),token:r.token,processingTimeMs:Math.round(r.time),timestamp:new Date().toISOString()},null,2);downloadFile('jwt-generated.json',json,'application/json');showToast('Downloaded JSON report','success');}

function exportPrint(){window.print();}
function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}
function reset(){elements.algoSelect.value='HS256';elements.headerInput.value='{"alg":"HS256","typ":"JWT"}';elements.payloadInput.value='{"sub":"1234567890","name":"John Doe","iat":1516239022}';elements.secretInput.value='your-secret-key';elements.secretField.style.display='block';elements.tokenDisplay.className='jwtg-token';elements.tokenDisplay.innerHTML='';state.lastToken='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}
function formatBytes(bytes){if(!bytes)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
